                "type": "paragraph",
                "text": "GPS en officiële afstand: gebruik verstreken tijd bij officiële 5-km-punten als belangrijkste controle. GPS kan meer of minder meten en je loopt mogelijk meer dan de kortste lijn. 42,5 GPS-km bij 5:27/km is 3:51:38, ondanks een schijnbaar correcte horlogepace. Neem nette bochten en loop soepel; geen voortdurende correcties op instant pace. Gebruik de tijdsdefinitie van de organisator: netto of bruto."
