            "text": "Standaard: geen afstandworkout die eindigt op 42,195 GPS-km. Start/stop de gewone activiteit op de officiële lijnen. Auto Lap 1 km voor rondetempo; check daarnaast officiële 5-km-tijden. Gebruik scherm 1 rondetempo/hartslag/afstand en scherm 2 gemiddeld tempo/cadans/verstreken tijd. Geen verplichte HR-zone of pace-alert."
