            "type": "paragraph",
            "text": "Connect-workout als je die wilt gebruiken: één stap Hardlopen → Duur: Rondeknop indrukken → Doel: Geen doel, geen repeats, geen ingebouwde warming-up/cooldown. Start op de startlijn en stop bij de officiële finish. Dit is één open racestap; LAP zou die stap beëindigen. De gewone activiteit is handiger wanneer je handmatig rondes wilt maken."
