            "text": "Voor handmatige rondes bij officiële markeringen: zet Auto Lap uit om dubbele rondes te vermijden. Kies vooraf één geteste methode. Voedingsmeldingen/timer vóór de race oefenen; gelmomenten in §6 zijn minuten sinds de start. Voorstartvoeding is apart."
