            "text": "Race-duurcontrole: A-doel 230 min; 5 min voorstart + race 230 + circa 5 min nafinish = circa 240 min totale aanwezigheid in deze drie bewegingsonderdelen, maar uitsluitend 230 min in de racetimer. Geen loopbandmarathon als alternatieve wedstrijd toevoegen."
