            "type": "paragraph",
            "text": "Deze plaatsing geeft circa 96 uur van woensdag-MP tot zondag-duur en circa 72 uur van zondag-duur tot de volgende MP-sessie, bij vergelijkbare starttijden. Maandag is een volledige rustdag na de duurloop. Duurlopen staan zeven dagen uiteen. Donderdag is een korte easy-run na de MP-sessie; vrijdag is volledige rust. De zaterdagrun blijft easy, zonder fast finish."
