            "text": "Vrije dagkeuze blijft mogelijk: schuif sessies met minimaal 48 uur tussen MP en lange duur in beide richtingen, bij voorkeur 72 uur of meer, en een volledige rustdag na lange duur. Houd lange duurlopen ongeveer 6–8 dagen uiteen. Geen dubbele sessies om vijf loopdagen administratief te halen."
