            "type": "paragraph",
            "text": "Keuze over sneller werk: geen extra blokken op 5:00–5:15/km in deze versie. De nieuwe vijfde loopdag, duurprogressie en langere MP-blokken geven al een stevige nieuwe belasting. Een tweede intensieve prikkel heeft binnen deze vier opbouwweken minder prioriteit dan goed uitgevoerde MP en lange duur. Dat is een inhoudelijke keuze; alle voorgeschreven MP blijft staan."
