      "8": {
        "title": "Onderbouwing en bronnen",
        "blocks": [
          {
            "type": "paragraph",
            "text": "V9.2 behoudt de bronverwijzingen uit de eerdere versies; twee onafhankelijke analyses zijn besproken, maar de persoonlijke weekindeling is een coachingskeuze, geen rechtstreeks wetenschappelijk bewezen optimum. De exacte sessieduren en progressie zijn individuele planningskeuzes; onderzoek valideert dit persoonlijke schema of een kans op 3:50 niet. De vernieuwde weekverdeling en het praktische voedingsplan zijn op 8 oktober 2026 vastgelegd."
          },
          {
            "type": "paragraph",
            "text": "1. Belastingssprongen: Frandsen e.a. (2025), cohort van 5.205 lopers: grotere afstanden in één sessie ten opzichte van de langste run in de voorafgaande 30 dagen waren geassocieerd met meer overbelastingsblessures. Observationeel, dus geen harde veilige grens. Dit maakt vooral de lange-duurprogressie en W41→42 relevant; bescheiden weekvolume sluit sessierisico niet uit. [BJSM](https://bjsm.bmj.com/content/59/17/1203)."
          },
          {
            "type": "paragraph",
            "text": "2. Taper: Wang e.a. (2023), meta-analyse: volumevermindering met behoud van intensiteitsprikkels kan duurprestaties verbeteren. De exacte optimale taper verschilt per sport en persoon. Twee weken met korte MP en minder volume is de praktische vertaling in V9.2. [PLOS ONE](https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0282838)."
          },
          {
            "type": "paragraph",
            "text": "3. Sportvoeding: Thomas, Erdman & Burke (2016), gezamenlijke position statement over voeding en sportprestatie. Voeding afstemmen op inspanningsduur, belasting en individuele omstandigheden. [PubMed / DOI](https://pubmed.ncbi.nlm.nih.gov/26920240/)."
          },
          {
            "type": "paragraph",
            "text": "4. Koolhydraten tijdens lange inspanning: Wallis & Podlogar (2022), onderzoeksgerichte review: voor langdurige inspanning kunnen hogere innames tot circa 90 g/u met glucose-fructosemengsels passen. Dit is geen persoonlijke absorptietest. [GSSI](https://www.gssiweb.org/research/article/dietary-carbohydrate-and-the-endurance-athlete-contemporary-perspectives)."
          },
          {
            "type": "paragraph",
            "text": "5. Productinhoud: officiële SiS Beta Fuel Energy Gel-informatie vermeldt 40 g koolhydraten per gel. V9.2 gebruikt dat voor de voorraadberekeningen, zonder marketingclaims over noodzakelijke hoge doseringen over te nemen. [Science in Sport](https://www.scienceinsport.com/eu/shop-sis/all-products/beta-fuel-gels-sis)."
          },
          {
            "type": "paragraph",
            "text": "6. Garmin: officiële uitleg voor aangepaste workouts en de FR165-handleiding. Exacte appbenamingen en aangeboden profielen kunnen per softwareversie verschillen. [Garmin Connect-workouts](https://support.garmin.com/nl-NL/?faq=wZ52AaLbLG2GC1Lxu2l4k7) · [FR165-handleiding](https://static.garmin.com/pumac/forerunner165series_OM_EN-SG.pdf)."
          }
        ]
      },
